"""Generate docs/VALIDATION_UK.md and the README results block from result files. Never edit by hand."""
from __future__ import annotations

import json
import re
from pathlib import Path

from .facts import facts

ROOT = Path(__file__).resolve().parents[2]
R = ROOT / "results"
START, END = "<!-- RESULTS:START (generated by taadeel.report, do not edit) -->", "<!-- RESULTS:END -->"


def pct(x) -> str:
    return "n/a" if x is None else f"{100 * x:.1f}%"


def build() -> tuple[str, str]:
    uk = json.loads((R / "uk_validation.json").read_text())
    am = json.loads((R / "uk_amending.json").read_text())
    ho = json.loads((R / "heldout_synthetic.json").read_text())
    ag = uk["aggregate"]
    al, cl = ag["alignment_one_day"], ag["classes_one_day"]
    pit, rec, ev, rv = ag["point_in_time"], ag["recorded_effects"], ag["engine_vs_recorded_effects"], ag["renumbering_variant"]

    head = (f"**Held-out synthetic (clean, run once): {ho['hits']} of {ho['total']} point predictions within +/- 0.05 of the "
            f"predicted value (a calibration count, not an accuracy); "
            f"{sum(v['ok'] for v in ho['directional'].values())} of {len(ho['directional'])} directional claims held.** "
            f"**Real UK data (English, England and Wales view only): alignment on one day windows {pct(al['accuracy'])} "
            f"({al['correct']} of {al['shared_sections']} sections; easy pairs, the engine also sees section numbers); point in time on the day before a change "
            f"{pct(pit['prior_day_accuracy'])} ({pit['prior_day_correct']} of {pit['prior_day_queries']}), "
            f"on the change date {pct(pit['on_date_accuracy'])} (this half is easy by construction).** "
            f"UAE law: unvalidated.")

    L = ["# UK real data validation (generated)", "",
         "Generated by `python -m taadeel.report` from `results/uk_validation.json` and `results/uk_amending.json`. Do not edit by hand.",
         "Contains public sector information licensed under the Open Government Licence v3.0.", "",
         "**Scope: this validates the locked engine on English UK Public General Acts (England and Wales view, body sections). "
         "It says nothing about UAE law, Arabic text or UAE drafting.** The engine files were not modified or tuned for it. "
         "Ground truth is editorial (legislation.gov.uk revised versions and effects), not a legal original, and the hand check was done by the project author's tooling, not by a lawyer or any independent reviewer.", "",
         "## Headline", "", head, "",
         "## Alignment and diff classification (one day windows)", "",
         f"Pairs: the snapshot on the day before each recorded effect date against the snapshot on that date. Truth: same section id means same section; text differs means replaced. "
         f"The engine does not use section ids for matching (it does see the section number and suffix, worth 5% of the pair score).", "",
         f"Alignment: {al['correct']} correct of {al['shared_sections']} shared sections ({pct(al['accuracy'])}); wrong {al['wrong']}; unmatched {al['unmatched']}; false matches {al['false_matches']}; low confidence pairs {al['low_confidence_pairs']}.", "",
         "| class | TP | FP | FN | precision | recall |", "|---|---|---|---|---|---|"]
    for c, d in cl.items():
        L.append(f"| {c} | {d['tp']} | {d['fp']} | {d['fn']} | {pct(d['precision'])} | {pct(d['recall'])} |")
    L += ["", "One day windows change little text, so these are easy cases. Long gap pairs (first to latest snapshot) per Act are below.", "",
          "## Per Act", "", "| Act | one day windows | long gap: shared | long gap: correct | long gap: low confidence | long gap class counts (TP/FP/FN) |", "|---|---|---|---|---|---|"]
    for a in uk["acts"]:
        lg = a["long_gap"]
        if lg:
            cc = "; ".join(f"{k} {v.get('tp',0)}/{v.get('fp',0)}/{v.get('fn',0)}" for k, v in sorted(lg["classes"].items()))
            L.append(f"| {a['act']} | {a['windows']} | {lg['shared']} | {lg['correct']} | {lg['low_conf_pairs']} | {cc} |")
    L += ["", "## Recorded effects against snapshots and against the engine", "",
          f"Effects checked (dated, usable, England and Wales): {rec['effects_checked']}. Snapshot shows a change at the named section on that date: {rec['effects_with_snapshot_change']} ({pct(rec['effects_with_snapshot_change']/rec['effects_checked'])}); class agrees in {rec['effects_class_agrees']}.",
          f"Snapshot changes in the windows: {rec['snapshot_changes']}; with a recorded dated effect: {rec['snapshot_changes_with_effect']} ({pct(rec['snapshot_changes_with_effect']/rec['snapshot_changes'])}). The rest are changes the usable dated effects do not explain (undated, ambiguous, prospective or lagging effects).",
          f"Engine against recorded effects (section level, class must agree): TP {ev['tp']}, FN {ev['fn']}, FP {ev['fp']}. The engine matched the snapshots exactly, so these disagreements come from the recorded effects data (or from this project's reading of it), not from alignment.", "",
          "## Point in time", "",
          f"A timeline is built from the base snapshot plus one version per recorded effect date; for each date D the engine is asked for D minus one day and D, and the text served is compared with an independently fetched snapshot. "
          f"Day before D: {pit['prior_day_correct']} of {pit['prior_day_queries']} correct ({pct(pit['prior_day_accuracy'])}). This is the real test. On D: {pit['on_date_correct']} of {pit['on_date_queries']} ({pct(pit['on_date_accuracy'])}); the version served on D is the snapshot used as truth, so this half cannot fail and is not evidence. Pooled {pct(pit['accuracy'])}, reported for completeness only. "
          "Every failure is a case where the site's snapshot on D minus one day differs from the previous recorded effect version, so a change took effect on a date the recorded effects did not give. "
          "This is a real limit of building a timeline from effects alone.", "",
          "| Act | queries | correct | wrong |", "|---|---|---|---|"]
    for p in uk["point_in_time"]:
        L.append(f"| {p['act']} | {p.get('queries',0)} | {p.get('correct',0)} | {p.get('wrong',0)} |")
    L += ["", "## Renumbering variant (real text, synthetic renumbering)", "",
          f"UK drafting rarely renumbers, so a labelled variant inserts a section and shifts later numbers by one: {rv['correct']} of {rv['sections']} sections aligned correctly ({pct(rv['accuracy'])}) across {rv['runs']} runs; the inserted section was found {rv['inserted_detected']} of {rv['runs']} times. This text is real but the renumbering is synthetic.", "",
          "## English amendment by reference patterns", "",
          f"Sample: {am['fetched']} amending Act sections fetched, {am['instruction_bearing']} contain amendment keywords. Split by SHA-1 parity of the URL into dev and test. Patterns were extended after reading the dev half only and frozen in the commit titled \"Freeze English amendment patterns before the test half is measured\"; `results/uk_amending.json` was generated after that commit and the test half was measured once per pattern set. Truth: recorded effects naming the amending section. Very small sample, effects from the same section are correlated, treat as indicative.", "",
          "| split | patterns | sections | effects | found | recall | parsed instructions | matching a recorded effect (precision lower bound) |", "|---|---|---|---|---|---|---|---|"]
    for part in ("dev", "test"):
        for k, lab in (("original_patterns", "original four"), ("extended_patterns", "extended")):
            d = am[part][k]
            L.append(f"| {part} | {lab} | {d['sections']} | {d['recorded_effects']} | {d['effects_found']} | {pct(d['recall'])} | {d['parsed_instructions']} | {d['instructions_matching_a_recorded_effect']} ({pct(d['precision_lower_bound'])}) |")
    L += ["", "The Arabic lexicon (`amend_ar.py`) has no real text to be measured against and is **unvalidated on real UAE text**.", "",
          *extra_uk_sections(facts()),
          "## Defects found during validation (disclosed)", "",
          "The first full run and a hand check of a sample of recorded effects exposed three defects in the effects reader (`clml.py`), not in the locked engine. They were fixed and the evaluation re-run; the earlier result files are kept as `results/uk_validation_run1.json`, `run2` and `run3`.",
          "1. A subsection effect such as `S. 14(2) repealed` was read as a whole section repeal.",
          "2. A date such as `1.10.2007 for S. and 1.10.2008 otherwise` was resolved to the second date; the meaning of `S.` is not in the retrieved terms, so such dates are now ambiguous and excluded.",
          "3. Northern Ireland only versions of a section with the same id were not dropped, giving duplicate section ids in three snapshots (the evaluator silently overwrote them). Duplicates now raise an error.", "",
          "## Known limits", "",
          "* Some recorded effects show no snapshot change on their date (examples are in `results/uk_handcheck.json`, including Theft Act 1968 s. 12A and s. 24A insertions and Misuse of Drugs Act 1971 insertions dated 1 July 1991). The cause was not established; one possibility, not tested, is that the site does not create a version at every effect date.",
          "* Schedules are out of scope. Devolved material is out of scope. Prospective changes are excluded.",
          "* Hand check by the project author's tooling, not a lawyer or an independent reviewer (files: `results/uk_handcheck.json`, `results/uk_handcheck_run1_sample.json`, script `uk_handcheck.py`, seed 20261012). A seeded draw of 20 disagreeing effects from the first run exposed defects 1 and 2 above. After the fixes, 10 seeded agreeing effects were read against their wording and all 10 matched, and the remaining disagreements (listed with the dates at which the section does change) were read; they are the unexplained cases in the previous bullet plus effects whose snapshot change falls on another date.", ""]
    F = facts()
    more = []
    if "v2_verdict" in F:
        more.append(f"* Alignment v2 (pre registered, new held out seeds and UK pairs): {F['v2_hits']} of {F['v2_total']} point predictions within tolerance, "
                    f"{F['v2_dir_hits']} of {F['v2_dir_total']} directional claims held. {F['v2_verdict']} [`docs/HELDOUT_V2_RESULTS.md`](docs/HELDOUT_V2_RESULTS.md)")
    if "tl_queries" in F:
        more.append(f"* Point in time with snapshot evidence (UK, pre registered): certain and wrong answers on the day before a change fall from {F['tl_old_wrong']} to {F['tl_certain_wrong']} of {F['tl_queries']}; "
                    f"{F['tl_uncertain']} answers are marked uncertain, with the true text among the candidates in {F['tl_uncertain_hit']}.")
    if "am2_recall" in F:
        more.append(f"* English amendment patterns on a second, larger UK sample (frozen, run once): recall {F['am2_recall']} ({F['am2_found']} of {F['am2_effects']} recorded effects), precision lower bound {F['am2_prec']}.")
    if "ar_cases" in F:
        more.append(f"* Arabic: synthetic stress set only ({F['ar_cases']} cases; locked normaliser {F['ar_v1_ok']} pass). No real UAE Arabic text is validated. [`docs/VALIDATION_ARABIC.md`](docs/VALIDATION_ARABIC.md)")
    if "akn_valid" in F:
        more.append(f"* Akoma Ntoso compatible export: {F['akn_valid']} of {F['akn_total']} samples validate against the OASIS schema (compatible, not compliant). [`docs/AKN_EXPORT.md`](docs/AKN_EXPORT.md)")
    block = "\n".join([START, "", head, "", *more, *([""] if more else []),
                       "Details: [`docs/VALIDATION_UK.md`](docs/VALIDATION_UK.md), [`docs/HELDOUT_RESULTS.md`](docs/HELDOUT_RESULTS.md). "
                       "Real UK numbers validate English UK legislation only. They say nothing about UAE law.", "", END])
    return "\n".join(L), block


def extra_uk_sections(F: dict) -> list[str]:
    L: list[str] = []
    if "am2_recall" in F:
        L += ["## Second English amendment sample (2026-10-16, frozen patterns, run once)", "",
              f"Selection rules were written down before fetching (`docs/DECISIONS.md` items 6 and 7): the {F['am2_fetched']} texts are the 11 amending sections the first rule had not yet taken and the schedule paragraphs cited by recorded effects. "
              f"{F['am2_bearing']} contain amendment keywords. None was read before the patterns were frozen, so both halves are out of sample. Result file: `results/uk_amending_2.json`.", "",
              f"* Extended (frozen) patterns: recall {F['am2_recall']} ({F['am2_found']} of {F['am2_effects']} recorded effects); precision lower bound {F['am2_prec']} ({F['am2_matched']} of {F['am2_instr']} parsed instructions match a recorded effect).",
              f"* Schedule paragraphs alone: recall {F['am2_sched_recall']} ({F['am2_sched_found']} of {F['am2_sched_effects']}). Original four patterns on all texts: recall {F['am2_orig_recall']}.",
              f"* The first sample's test half gave {F['am1_test_recall']} on {F['am1_test_effects']} effects; the larger, independent sample gives a lower figure, which is the better estimate. "
              "A common shape in schedules, \"Section N ... is amended as follows\", is not covered by any frozen pattern. Only effects on the 7 validated Acts have truth, so precision is a lower bound.", ""]
    if "tl_queries" in F:
        L += ["## Point in time from snapshots (pre registered, run once)", "",
              "Predictions: `docs/PREDICTIONS_TIMELINE.md`. Method: `src/taadeel/timeline_v2.py` (the locked `temporal.py` is not edited). Result file: `results/uk_timeline_v2.json`. "
              "A snapshot change that no recorded effect of that date explains marks the interval before it as uncertain, with two candidate texts.", "",
              "| method | queries (day before a change) | certain and correct | certain and wrong | uncertain, truth among candidates | uncertain, truth missing |",
              "|---|---|---|---|---|---|",
              f"| effects only (old) | {F['tl_queries']} | {F['tl_old_correct']} | {F['tl_old_wrong']} | 0 | 0 |",
              f"| effects plus snapshot evidence (new) | {F['tl_queries']} | {F['tl_certain_correct']} | {F['tl_certain_wrong']} | {F['tl_uncertain_hit']} | {F['tl_uncertain_miss']} |", "",
              f"Predictions: {F['tl_pred_hits']} of {F['tl_pred_total']} hit ({F['tl_pred_detail']}). Cost: in {F['tl_uncertain_first']} of the {F['tl_uncertain']} uncertain answers the old certain answer was already right; the new method trades those for fewer confident errors. "
              "The candidate texts come from the snapshot after the change, so the method needs periodic snapshots, which the UAE portal does not currently allow to be collected.", ""]
    return L


def arabic_doc(F: dict) -> str:
    return "\n".join([
        "# Arabic handling: what is and is not validated (generated)", "",
        "Generated by `python -m taadeel.report` from `results/arabic_stress.json` and `results/arabic_wikisource_probe.json`. Do not edit by hand.", "",
        "**No permitted real Arabic legal text is held, so nothing here is a validation on UAE law.**", "",
        "## Synthetic stress set (test strings, not legislation)", "",
        f"{F['ar_cases']} cases covering diacritics, tatweel, alef and yaa variants, Arabic Indic and Persian digits, «مكرر», mixed Arabic and English, and invisible format characters (`src/taadeel/arabic_stress.py`). "
        f"The locked v1 normaliser passes {F['ar_v1_ok']} of {F['ar_cases']}; on article labels {F['ar_label_v1_ok']} of {F['ar_label_cases']}. Its gaps: right to left and zero width marks, the byte order mark, the Arabic letter mark, Farsi yeh and keheh, ornate parentheses and a dash before «مكرر». "
        f"`normalize_v2.py` pre cleans these and passes {F['ar_v2_ok']} of {F['ar_cases']}, but it was written after seeing the cases, so that score is by construction. It is not the default.", "",
        "## One real Arabic law, counts only", "",
        f"Arabic Wikisource, Federal Law No. 7 of 2002 (oldid 137670), read under its robots.txt; its reuse status is not clear, so no wording is committed (`docs/DATA_SOURCES.md`). On a local copy the parser found {F['ws_articles']} articles numbered 1 to {F['ws_max']} with {F['ws_missing']} missing; "
        f"a renumbering variant (real text, synthetic renumbering) aligned {F['ws_renumber_v1']} articles with v1 and {F['ws_renumber_v2']} with v2. One wiki transcription is a smoke test, not a validation set.", "",
        "## Not validated", "",
        "* Any real UAE federal law text, consolidated version or amending instrument.",
        "* Arabic amendment by reference patterns (`amend_ar.py`): invented samples only.",
        "* Effective date extraction from Arabic text; Hijri dates; Gazette references.",
        "* OCR of scanned Arabic PDFs; the PDF extractor is tested on synthetic PDFs only.",
        "* Search quality for Arabic (no clitic stripping or stemming).", ""])


def akn_doc(F: dict) -> str:
    return "\n".join([
        "# Akoma Ntoso export (generated)", "",
        "Generated by `python -m taadeel.report` from `results/akn_validation.json`. Do not edit by hand.", "",
        f"**AKN compatible, not AKN compliant.** {F['akn_valid']} of {F['akn_total']} sample documents (synthetic and UK English) validate against the OASIS Akoma Ntoso 1.0 schema `akomantoso30.xsd` (CC BY 4.0); "
        f"{F['akn_controls']} of {F['akn_controls_total']} deliberately broken documents are rejected, which shows the check is effective.", "",
        "Covered: FRBR identification (Work, Expression, Manifestation), parts, chapters, articles and clauses, and provenance (source URL, retrieval date, synthetic flag) under `<proprietary>`.",
        "Not covered: lifecycle events, active and passive modifications, temporal groups, references to amending acts, and an official naming convention for URIs. Schema validity checks structure only, not meaning.",
        "Reproduce: save the schema and `xml.xsd` from the OASIS URL in `docs/DATA_SOURCES.md`, then `python -m taadeel.akn_export validate DIR` (the sha256 of both files is checked).", ""])


def render_templates(F: dict) -> list[Path]:
    out = []
    tdir = ROOT / "docs" / "templates"
    for t in sorted(tdir.rglob("*.md")):
        dest = ROOT / "docs" / t.relative_to(tdir)
        dest.parent.mkdir(parents=True, exist_ok=True)
        dest.write_text(t.read_text(encoding="utf-8").format_map(F), encoding="utf-8", newline="\n")
        out.append(dest)
    return out


def main() -> None:
    F = facts()
    if "ar_cases" in F:
        (ROOT / "docs" / "VALIDATION_ARABIC.md").write_text(arabic_doc(F), encoding="utf-8", newline="\n")
    if "akn_valid" in F:
        (ROOT / "docs" / "AKN_EXPORT.md").write_text(akn_doc(F), encoding="utf-8", newline="\n")
    if (ROOT / "docs" / "templates").exists():
        render_templates(F)
    doc, block = build()
    (ROOT / "docs" / "VALIDATION_UK.md").write_text(doc, encoding="utf-8", newline="\n")
    rd = ROOT / "README.md"
    t = rd.read_text(encoding="utf-8")
    if START in t:
        t = re.sub(re.escape(START) + r".*?" + re.escape(END), block, t, flags=re.S)
    else:
        t = t.replace("## Status", block + "\n\n## Status", 1)
    rd.write_text(t, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
